"""Real C ABI evidence for generated byte patterns."""

import os

import pytest

from agent_moss.engine.prefilter_native import NativeLibrary, NativeScanError


def _library():
    path = os.environ.get("AGENT_MOSS_TEST_HS_LIB")
    if not path:
        pytest.skip("set AGENT_MOSS_TEST_HS_LIB to a real Hyperscan compile library")
    return NativeLibrary(path, backend="hyperscan")


def test_real_native_compile_load_and_complete_scan():
    library = _library()
    expressions = [r"\x63\x75\x72\x6c", r"\x63\x75\x72\x6c(?s:.*)\x68\x74\x74\x70"]
    database = library.load(library.compile(expressions), len(expressions))
    try:
        assert database.scan(b"curl https://") == {0, 1}
        assert database.scan(b"https:// curl") == {0}
        assert database.scan(b"echo") == set()
    finally:
        database.close()


def test_closed_native_database_is_an_error_not_an_empty_result():
    library = _library()
    database = library.load(library.compile([r"\x61\x62"]), 1)
    database.close()
    with pytest.raises(NativeScanError):
        database.scan(b"ab")
